inline std::unique_ptr<juce::Drawable> make(bool vertical, juce::Colour colour) {
    auto xml = juce::XmlDocument::parse(juce::String::fromUTF8(vertical ? verticalSvg() : horizontalSvg()));
    if (!xml) return nullptr;
    auto dr = juce::Drawable::createFromSVG(*xml);
    if (dr) dr->replaceColour(juce::Colours::white, colour);
    return dr;
}
